import{_ as t,o as a,c as r,a6 as i}from"./chunks/framework.BV_S2lHy.js";const p=JSON.parse('{"title":"Evaluation protocol","description":"","frontmatter":{},"headers":[],"relativePath":"benchmark/protocol.md","filePath":"benchmark/protocol.md","lastUpdated":1792247050000}'),o={name:"benchmark/protocol.md"};function n(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="evaluation-protocol" tabindex="-1">Evaluation protocol <a class="header-anchor" href="#evaluation-protocol" aria-label="Permalink to &quot;Evaluation protocol&quot;">​</a></h1><p>This protocol characterizes robot-side performance across HiveBoard attachments. It is suitable for teleoperated arms, wearable interfaces, exoskeletons, and autonomous policies, provided that the control mode is held constant across the recorded trials being compared.</p><p>The source protocol is available in <a href="https://github.com/hiveboard-bench/HiveBoard/blob/main/Documentation/PROTOCOL.md" target="_blank" rel="noreferrer"><code>Documentation/PROTOCOL.md</code></a>. Submissions through this documentation require all 13 conditions, with five recorded trials per condition (65 trials).</p><p>Before recording, open <a href="/hivedocs/benchmark/tasks">How to perform each task</a>. It lists the starting state, required actions, success criterion, timeout, and reset for every condition, including the <a href="/hivedocs/benchmark/tasks#shock-absorber">shock absorber</a>.</p><h2 id="required-material" tabindex="-1">Required material <a class="header-anchor" href="#required-material" aria-label="Permalink to &quot;Required material&quot;">​</a></h2><ul><li>One printed HiveBoard base.</li><li>The complete attachment set, including the four-piece friction-ring accessory for the ball-valve ring condition.</li><li>One manipulation platform: an end-effector plus the system that positions and commands it.</li><li>The <a href="/hivedocs/benchmark/evaluation-runner">Evaluation Runner</a> or supplied trial logging template.</li><li>An external camera with a view of the board and end-effector.</li></ul><h2 id="prepare-the-setup" tabindex="-1">Prepare the setup <a class="header-anchor" href="#prepare-the-setup" aria-label="Permalink to &quot;Prepare the setup&quot;">​</a></h2><ol><li>Fix the board to a rigid surface within the platform&#39;s working volume.</li><li>Record whether it is mounted horizontally or vertically.</li><li>Fully seat every attachment before starting.</li><li>Position the platform so that the board is not moved during a trial.</li><li>Save a photograph of the complete setup as <code>setup.jpg</code>.</li><li>Create <code>platform.md</code> with the end-effector, control interface or policy, mounting orientation, control mode, and relevant calibration notes.</li><li>Record the printer, material, print settings, and post-processing. The runner includes these fields in <code>platform.md</code>.</li></ol><h2 id="optional-hardware-variants" tabindex="-1">Optional hardware variants <a class="header-anchor" href="#optional-hardware-variants" aria-label="Permalink to &quot;Optional hardware variants&quot;">​</a></h2><p><a href="/hivedocs/hardware/aruco-cell">ArUco cells with IDs 0 and 1</a> can be used for board localization. Record each ID and marker-to-board transform with the setup.</p><p>The <a href="/hivedocs/hardware/ball-valve-360">360° ball-valve variant</a> is available for learning-based methods and controller debugging. It permits continued rotation beyond the quarter-turn target. The Ball valve success criterion remains 90° from closed to open. Mark the initial and target orientations, and record <code>ball_valve_360</code>, the asset commit, and any friction ring in <code>platform.md</code>. In the runner, use <strong>Calibration notes</strong> for these details. Identify the hardware variant when comparing results. These additions introduce no new scored conditions.</p><h2 id="optional-dataset-collection" tabindex="-1">Optional dataset collection <a class="header-anchor" href="#optional-dataset-collection" aria-label="Permalink to &quot;Optional dataset collection&quot;">​</a></h2><p>We encourage labs to record robot states, executed commands, and camera streams during evaluation using <a href="/hivedocs/guides/datahive">DataHive</a>. Test the recording setup before the scored trials and link each episode to its benchmark trial record. Dataset collection is optional and does not change the task criteria, timing, or requirement for 65 trials. The <a href="/hivedocs/guides/datahive#collect-during-a-benchmark-evaluation">DataHive guide</a> explains how to prepare both submissions; the <a href="/hivedocs/contribute/evaluations">learning-dataset call</a> also accepts larger collections and task subsets outside a formal evaluation.</p><h2 id="familiarization" tabindex="-1">Familiarization <a class="header-anchor" href="#familiarization" aria-label="Permalink to &quot;Familiarization&quot;">​</a></h2><p>Run unrecorded practice trials for each attachment until completion times stabilize. Begin recording after three consecutive practice trials finish within 20% of each other or within the timeout, whichever comes first.</p><p>Practice trials are not included in the submitted result.</p><h2 id="recorded-trials" tabindex="-1">Recorded trials <a class="header-anchor" href="#recorded-trials" aria-label="Permalink to &quot;Recorded trials&quot;">​</a></h2><p>For each platform and evaluation condition:</p><ol><li>Run <strong>five recorded trials</strong>.</li><li>Start the end-effector from the same neutral pose.</li><li>Start the external camera before the countdown. When using the runner, command the first task motion when the countdown reaches zero; this is when timing starts. For manual logging, start timing with the first commanded task motion.</li><li>Stop timing when the success criterion is met, a safety event occurs, or the timeout expires.</li><li>Reset the mechanism and neutral pose before the next trial.</li></ol><p>Timing includes the initial approach and grasp. Grasping remains stage 1 for Lock and key, Drawer, and Shock absorber. Picking up the loose bulb, nut, or peg is also included in the trial time.</p><p>Run the ball valve as two separate blocks: five trials without a friction ring and five with the ring fitted.</p><p>Do not tune parameters or change the control mode between recorded trials in the same condition. A restarted approach within a trial counts as another attempt. Count a regrasp only when the end-effector releases the part and grasps it again. The initial grasp is not a regrasp. Attempts and regrasps are separate counts; neither starts a new trial.</p><h2 id="thread-task-starting-state" tabindex="-1">Thread-task starting state <a class="header-anchor" href="#thread-task-starting-state" aria-label="Permalink to &quot;Thread-task starting state&quot;">​</a></h2><p>For Thread (M8) and Thread (M30), the nut must start completely removed from the fixed screw. Alignment and initial thread engagement are part of the task. Fully remove the nut again before each trial. The runner&#39;s images show the assembled mechanism with the nut on the screw. They do not define the starting state.</p><p>Record the starting configuration in <code>platform.md</code>. Identify any earlier trials that began with the nut already engaged, since their completion times exclude part of the task.</p><h2 id="drawer-starting-state-and-sequence" tabindex="-1">Drawer starting state and sequence <a class="header-anchor" href="#drawer-starting-state-and-sequence" aria-label="Permalink to &quot;Drawer starting state and sequence&quot;">​</a></h2><p>Start with the drawer completely removed from its housing and placed in its documented starting pose. The housing stays fixed to the board. Grasp the drawer, align it with the housing opening, and insert it fully until correctly seated. The 120 s timeout includes the initial approach and grasp. Remove the drawer completely before the next trial.</p><p>The stages are (1) grasp the drawer, (2) align it with the housing, and (3) insert it fully. Identify earlier trials that used an open-and-close sequence in <code>notes</code> when reporting results.</p><h2 id="outcomes" tabindex="-1">Outcomes <a class="header-anchor" href="#outcomes" aria-label="Permalink to &quot;Outcomes&quot;">​</a></h2><p>Use exactly one of these values:</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Meaning</th></tr></thead><tbody><tr><td><code>success</code></td><td>The full success criterion was completed within the timeout</td></tr><tr><td><code>fail</code></td><td>The trial ended unsuccessfully before the timeout</td></tr><tr><td><code>timeout</code></td><td>The success criterion was not completed before the limit</td></tr><tr><td><code>safety_stop</code></td><td>The trial ended because of a safety event</td></tr></tbody></table><p>Only successful trials receive a <code>completion_time_s</code> value.</p><h2 id="failure-causes" tabindex="-1">Failure causes <a class="header-anchor" href="#failure-causes" aria-label="Permalink to &quot;Failure causes&quot;">​</a></h2><p>Every unsuccessful trial must contain one dominant failure cause.</p><table tabindex="0"><thead><tr><th>Cause</th><th>Use when</th></tr></thead><tbody><tr><td><code>grasp_geometry</code></td><td>The end-effector cannot engage the part in a stable grasp</td></tr><tr><td><code>kinematic_limit</code></td><td>The platform cannot produce the motion required by the task</td></tr><tr><td><code>perception</code></td><td>Alignment or state could not be judged reliably</td></tr><tr><td><code>slip</code></td><td>A grasp was acquired and then lost</td></tr><tr><td><code>force_limit</code></td><td>Available grasp or actuation force was insufficient</td></tr><tr><td><code>control_precision</code></td><td>Control resolution was too coarse for the task</td></tr><tr><td><code>other</code></td><td>None of the listed causes fits; explain in <code>notes</code></td></tr></tbody></table><p>Choose one dominant cause even when several factors contributed.</p><h2 id="broken-or-displaced-parts" tabindex="-1">Broken or displaced parts <a class="header-anchor" href="#broken-or-displaced-parts" aria-label="Permalink to &quot;Broken or displaced parts&quot;">​</a></h2><p>If a part breaks or leaves its cell:</p><ol><li>stop the trial if continuation is unsafe;</li><li>record the trial as it occurred;</li><li>describe the event in <code>notes</code>;</li><li>reseat or replace the part; and</li><li>continue with the next scheduled trial.</li></ol><p>Do not silently replace the affected row with a rerun.</p><h2 id="reproducibility-checklist" tabindex="-1">Reproducibility checklist <a class="header-anchor" href="#reproducibility-checklist" aria-label="Permalink to &quot;Reproducibility checklist&quot;">​</a></h2><ul><li>[ ] The HiveBoard release or commit is recorded.</li><li>[ ] Printing parameters and post-processing are recorded.</li><li>[ ] All attachments are fully seated.</li><li>[ ] Familiarization is complete for every attachment.</li><li>[ ] Five recorded trials exist for all 13 conditions (65 trials total).</li><li>[ ] Timeouts and task criteria match the attachment reference.</li><li>[ ] Every unsuccessful trial has one failure cause.</li><li>[ ] Attempts, regrasps, and strategy are present on every row.</li><li>[ ] Composed assembly tasks include <code>stage_reached</code>.</li><li>[ ] Broken or reseated parts are described.</li><li>[ ] <code>setup.jpg</code> and <code>platform.md</code> accompany the log.</li><li>[ ] One external-camera recording accompanies each trial, using the filenames in <code>recording-instructions.md</code>.</li><li>[ ] No operator names or personal identifiers appear in the files.</li></ul>',42)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
